using System;using System.IO;using System.Linq;using Mono.Cecil;using Mono.Cecil.Cil;
public static class PvzModuleTool {
 static string Rename(string s){return s.Replace("S2EPvZFusionMod","ShenPulseFusion.Engine").Replace("S2EMode","FusionMode").Replace("Stream To Earn","ShenPulse").Replace("StreamToEarn","ShenPulse").Replace("S2E","ShenPulse").Replace("streamtoearn.io","shenpulse.leuridan.fr");}
 static void Types(TypeDefinition t){if(t.Namespace.StartsWith("S2EPvZFusionMod"))t.Namespace=Rename(t.Namespace);if(t.Name=="S2EMode")t.Name="FusionMode";foreach(var m in t.Methods.Where(x=>x.HasBody)){if(t.Name=="WebServer"&&m.Name=="InitializeHttpServer"){m.Body.ExceptionHandlers.Clear();m.Body.Instructions.Clear();m.Body.Instructions.Add(Instruction.Create(OpCodes.Ret));continue;}foreach(var i in m.Body.Instructions)if(i.OpCode==OpCodes.Ldstr)i.Operand=Rename((string)i.Operand);}foreach(var n in t.NestedTypes)Types(n);}
 public static void Main(string[] args){using(var module=ModuleDefinition.ReadModule(args[0])){module.Assembly.Name.Name="ShenPulse.Fusion.Engine";module.Name="ShenPulse.Fusion.Engine.dll";foreach(var t in module.Types)Types(t);foreach(var a in module.Assembly.CustomAttributes)for(int i=0;i<a.ConstructorArguments.Count;i++){var old=a.ConstructorArguments[i];if(old.Value is string)a.ConstructorArguments[i]=new CustomAttributeArgument(old.Type,Rename((string)old.Value));}module.Write(args[1]);}}
}
